# -*- coding: utf-8 -*-
# Класс «неверный вариант = ключ в другой записи» (численная сверка всех вариантов банка, 26.09).
# Закрываются только варианты, равные ключу по значению, когда условие НЕ требует особой формы записи
# (задания «сократите», «несократимой», «к общему знаменателю», «округлите до …», «исключите целую часть» не трогаются).
import json
H = {(t, i): (k, v) for t, i, k, v in json.load(open("/audit/numeq_hits.json"))}
S = "численная сверка вариантов с ключом + условие задачи, 26.09"
P = {}
DROP = {  # task: [indices]
 "G10_TB_2_4_2_d": [2], "G10_TB_3_7_3_c": [0], "G10_TB_§5_5_15_1": [0], "G11_TB_8_4_16_г": [0], "G11_TB_9_7*_9_60_3": [2],
 "G11_TB_?_64_б": [1], "G11_TB_§24_8_1": [2], "G5_TB_12_446.5": [2], "G5_TB_12_446.6": [2], "G6_TB_81–83_678.1": [1],
 "G6_TB_23_943": [1], "G7_ALG_34_2.9": [0], "G8_TB_11_279.3": [2], "G5_TB_63_1504.2": [2], "G5_TB_59_1392.4": [2],
 "G5_TB_56_1320.3": [1], "G5_TB_43_771": [1], "G6_TB_2_18.1": [1], "G6_TB_49–50_433.3": [0], "G6_TB_3_132.5": [0],
 "G6_TB_7_295.2": [0], "G6_TB_6_249.3": [0], "G6_TB_40–42_359.2": [1], "G6_TB_3_142.4": [0], "G5_TB_50_1217.3": [2],
 "G5_TB_50_1218.1": [0], "G6_TB_31–33_272": [1], "G6_TB_8_333": [2], "G6_TB_98–100_851.3": [1], "G6_TB_4_166": [0],
 "G5_TB_42_745.2": [2], "G6_TB_12_466": [0], "G6_TB_12_479": [0], "G11_TB_§3_12_3": [0], "G7_ALG_34_8.3": [0],
 "G7_ALG_34_2.7": [0], "G7_ALG_34_2.5": [0], "G7_ALG_34_10.14": [0], "G7_ALG_34_10.16": [0], "G7_ALG_34_10.8": [0],
 "G9_TB_37_479_2": [1], "G9_TB_37_479_4": [0], "G9_TB_37_479_3": [1], "G9_TB_3_25_з": [2], "G9_TB_УПК_732_5": [0],
 "G10_TB_§30_30_5_12": [1], "G11_TB_15_3*_15_15_1": [1], "G5_TB_33_1290": [2], "G5_TB_56_1323.1": [2], "G5_TB_56_1323.2": [1],
 "G6_TB_19–20_158.1": [0], "G6_TB_19–20_158.4": [2], "G6_TB_19–20_165": [2],
}
# key written as \dfrac{-a}{b}: take the canonical −\dfrac{a}{b} form of the equal option as the key (option closes automatically)
KFORM = {"G11_TB_11_5*_11_25_а": 0, "G11_TB_17_1*_16_52": 2, "G9_TB_18_295_3": 2, "G6_TB_34_1263.9": 0, "G8_TB_23_579.2": 0,
         "G9_TB_8_75_5": 0, "G10_TB_1_7_2": 0, "G10_TB_1_7_1": 2, "G7_TB_43_1087.3": None}
OPEN = ("задание допускает много верных ответов; вариант «{v}» — тоже набор дробей, равных данной, т. е. верный ответ среди неверных — закрыт")
for t, ix in DROP.items():
    vs = "; ".join(f"«{H[(t, i)][1]}»" for i in ix)
    why = (OPEN.format(v=H[(t, ix[0])][1]) if t.startswith("G6_TB_19–20_1") else
           f"неверный вариант {vs} равен ключу «{H[(t, ix[0])][0]}» по значению (другая запись того же числа/ответа), а условие не требует особой формы записи — верный ответ среди неверных, закрыт")
    P[t] = dict(why=why, src=S, drop=ix)
for t, i in KFORM.items():
    if i is None: continue
    k, v = H[(t, i)]
    P[t] = dict(why=f"ключ «{k}» записан с минусом в числителе; вариант «{v}» — тот же ответ в обычной записи, т. е. верный ответ среди неверных: запись ключа приведена к обычной, вариант закрыт", src=S, k=v)
P["G7_TB_43_1087.3"] = dict(why="вариант «u = 39/9, v = −10/9» равен ключу (39/9 = 13/3) — закрыт; ключ записан с минусом в числителе — приведён к обычной записи", src=S,
                            k=r"$u = \dfrac{13}{3}$, $v = -\dfrac{10}{9}$", drop=[2])
P["G6_TB_105–106_910"] = dict(why="вариант «25, 9, −39, −52» совпадал с ключом (ключ отличался только лишней «;» в конце) — ключ очищен, вариант закрыт", src=S, k=r"$25, 9, -39, -52$")
P["G6_TB_19–20_158.5"] = dict(why=OPEN.format(v="5/5, 6/6, 7/7") + "; также закрыт «1/1, 2/2, 3/3» (равны 4/4); добавлены 2 неверных варианта с описанием ошибки", src=S, drop=[0, 2],
    dadd=[(r"$\dfrac{4}{8}$, $\dfrac{4}{12}$, $\dfrac{4}{16}$", "Ученик умножил на 2, 3 и 4 только знаменатель, оставив числитель без изменения."),
          (r"$\dfrac{5}{4}$, $\dfrac{6}{4}$, $\dfrac{7}{4}$", "Ученик прибавлял 1, 2 и 3 к числителю, не изменяя знаменатель.")])
P["G6_TB_21–23_190"] = dict(why="в ключе к 1) указаны только 3 дроби вместо требуемых 4 (24/30 = 16/20 = 12/15 = 8/10 = 4/5), к 2) — 5 вместо 4; ключ приведён к 4 дробям в каждой части", src=S,
    k=r"1) $\dfrac{16}{20}, \dfrac{12}{15}, \dfrac{8}{10}, \dfrac{4}{5}$; 2) $\dfrac{6}{30}, \dfrac{4}{20}, \dfrac{3}{15}, \dfrac{2}{10}$")
P["G6_TB_12_466"]["dadd"] = [(r"$\dfrac{1}{10}$, $\dfrac{3}{10}$, $\dfrac{3}{2}$, $\dfrac{5}{2}$, $1$, $2$, $5$", "Ученик считал процент десятой частью числа и делил количество процентов на 10, а не на 100.")]
P["G6_TB_12_466"]["why"] += "; добавлен неверный вариант с описанием ошибки (осталось бы < 2 вариантов)"
